components/themevale/homepage/component/:
{{#each categories}}
    {{#if id '==' ../category_id}}
        <div class="themevale_productsByCategoryId">
            <h2 class="page-heading"><a href="{{url}}">{{name}}</a></h2>
            {{#if ../../has_count_down}}
                <div class="countDowntimer"><span class="text">Limited-Time Offers, End Ins:</span><span id="number">{{../../../has_count_down}}</span></div>
            {{/if}}
            <div class="page-content" data-themevale-products-by-category="{{url}}">
                {{> components/themevale/homepage/component/product-loading theme_settings=../../theme_settings}}
            </div>
        </div>
        
    {{else}}
        {{#each children}}
            {{#if id '==' ../../../category_id}}
                <div class="themevale_productsByCategoryId">
                    <h2 class="page-heading"><a href="{{url}}">{{name}}</a></h2>
                    {{#if ../../../../has_count_down}}
                        <div class="countDowntimer"><span class="text">Limited-Time Offers, End Ins:</span><span id="number">{{../../../../../has_count_down}}</span></div>
                    {{/if}}
                    <div class="page-content" data-themevale-products-by-category="{{url}}">
                        {{> components/themevale/homepage/component/product-loading theme_settings=../../../../theme_settings}}
                    </div>
                </div>
                
            {{else}}
                {{#each children}}
                    {{#if id '==' ../../../../../category_id}}
                        <div class="themevale_productsByCategoryId">
                            <h2 class="page-heading"><a href="{{url}}">{{name}}</a></h2>
                            {{#if ../../../../../../has_count_down}}
                                <div class="countDowntimer"><span class="text">Limited-Time Offers, End Ins:</span><span id="number">{{../../../../../../../has_count_down}}</span></div>
                            {{/if}}
                            <div class="page-content" data-themevale-products-by-category="{{url}}">
                                {{> components/themevale/homepage/component/product-loading theme_settings=../../../../../../theme_settings}}
                            </div>
                        </div>
                        
                    {{/if}}
                {{/each}}
            {{/if}}
        {{/each}}
    {{/if}}
{{/each}}
